<?php $edit = $sectionData['edit'] ?? null; ?>
<section class="admin-content">
  <div class="admin-section-intro"><div><span class="eyebrow">Audience</span><h2>Newsletter subscribers</h2><p>Manage opt-in contacts. Unsubscribed records are retained for auditability and are not deleted.</p></div></div>
